import React from 'react';
import {Easing, interpolate, spring, useCurrentFrame, useVideoConfig} from 'remotion';
import {FONTS, getVisualMeta} from '../editorConfig.js';

const clamp=(n,a=0,b=1)=>Math.max(a,Math.min(b,n));
const rgba=(hex,a)=>{const h=String(hex||'#000').replace('#','');const x=h.length===3?h.split('').map(c=>c+c).join(''):h;const n=parseInt(x,16)||0;return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${a})`};
const luminance=(hex)=>{const h=String(hex||'#000').replace('#','');const x=h.length===3?h.split('').map(c=>c+c).join(''):h;const n=parseInt(x,16)||0;const c=[(n>>16)&255,(n>>8)&255,n&255].map(v=>{v/=255;return v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4)});return .2126*c[0]+.7152*c[1]+.0722*c[2]};
const contrast=(a,b)=>{const A=luminance(a),B=luminance(b);return (Math.max(A,B)+.05)/(Math.min(A,B)+.05)};
const inkOn=(a,b=a)=>Math.min(contrast('#14161A',a),contrast('#14161A',b))>=Math.min(contrast('#FFFFFF',a),contrast('#FFFFFF',b))?'#14161A':'#FFFFFF';
const fontFor=(k)=>FONTS[k]||FONTS.body;
const enter=(frame,fps,delay=0)=>spring({frame:Math.max(0,frame-delay),fps,config:{damping:16,stiffness:130,mass:.65}});
const fadeOut=(frame,dur)=>interpolate(frame,[Math.max(0,dur-8),Math.max(1,dur-1)],[1,0],{extrapolateLeft:'clamp',extrapolateRight:'clamp'});
const pathProgress=(frame,dur,start=.05,end=.55)=>clamp(interpolate(frame,[dur*start,dur*end],[0,1],{extrapolateLeft:'clamp',extrapolateRight:'clamp',easing:Easing.out(Easing.cubic)}));
const numberFromText=(v)=>{const m=String(v||'').replace(/,/g,'').match(/[+-]?\d+(?:\.\d+)?/);return m?Number(m[0]):null};

function Icon({name='chart',color='#111',size=24,stroke=2}){
  const common={width:size,height:size,viewBox:'0 0 24 24',style:{display:'block'}};
  const line={fill:'none',stroke:color,strokeWidth:stroke,strokeLinecap:'round',strokeLinejoin:'round'};
  if(name==='play')return <svg {...common}><path d="M8 5v14l11-7z" fill={color}/></svg>;
  if(name==='check')return <svg {...common}><path d="M4 12.5l5 5L20 6" {...line}/></svg>;
  if(name==='cross')return <svg {...common}><path d="M6 6l12 12M18 6L6 18" {...line}/></svg>;
  if(name==='heart')return <svg {...common}><path d="M12 21s-7-4.6-9.5-9C.7 8.4 2.3 4.8 5.7 4.1 8 3.6 10.3 4.7 12 7c1.7-2.3 4-3.4 6.3-2.9 3.4.7 5 4.3 3.2 7.9-2.5 4.4-9.5 9-9.5 9z" fill={color}/></svg>;
  if(name==='comment'||name==='chat')return <svg {...common}><path d="M4 5h16a1 1 0 0 1 1 1v10a1 1 0 0 1-1 1H9l-5 4v-5H4a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1z" {...line}/></svg>;
  if(name==='share'||name==='send')return <svg {...common}><path d="M3 11l18-8-8 18-2.5-7.5L3 11z" {...line}/></svg>;
  if(name==='bookmark')return <svg {...common}><path d="M6 3h12v18l-6-4-6 4V3z" fill={color}/></svg>;
  if(name==='pin')return <svg {...common}><path d="M12 21s7-6.5 7-11.5a7 7 0 1 0-14 0C5 14.5 12 21 12 21z" fill={color}/><circle cx="12" cy="9.5" r="2.4" fill="#fff" opacity=".9"/></svg>;
  if(name==='star')return <svg {...common}><path d="M12 2.5l2.9 6 6.6.7-5 4.4 1.4 6.5L12 16.8 6.1 20l1.4-6.5-5-4.4 6.6-.7z" fill={color}/></svg>;
  if(name==='target')return <svg {...common}><circle cx="12" cy="12" r="9" {...line}/><circle cx="12" cy="12" r="5" {...line}/><circle cx="12" cy="12" r="1.8" fill={color}/></svg>;
  if(name==='shield')return <svg {...common}><path d="M12 2l8 3.5v6c0 5-3.4 8.7-8 10.5-4.6-1.8-8-5.5-8-10.5v-6L12 2z" fill={color}/></svg>;
  if(name==='arrowRight')return <svg {...common}><path d="M5 12h14M13 6l6 6-6 6" {...line}/></svg>;
  if(name==='arrowUp'||name==='trend')return <svg {...common}><path d="M4 17l6-6 4 4 6-9M14 6h6v6" {...line}/></svg>;
  if(name==='bag')return <svg {...common}><path d="M6 9h12l-1 11H7L6 9z" fill={color}/><path d="M9 9V7a3 3 0 0 1 6 0v2" {...line}/></svg>;
  if(name==='wifi')return <svg {...common}><circle cx="12" cy="18" r="1.5" fill={color}/><path d="M7 14a7 7 0 0 1 10 0M3 10a13 13 0 0 1 18 0" {...line}/></svg>;
  if(name==='gift')return <svg {...common}><rect x="3" y="9" width="18" height="4" rx="1" fill={color}/><rect x="4.5" y="13" width="15" height="8" rx="1" fill={color} opacity=".8"/><path d="M12 9v12M12 9c-2-4-7-4-7-1s4 1 7 1m0 0c2-4 7-4 7-1s-4 1-7 1" {...line}/></svg>;
  if(name==='trophy')return <svg {...common}><path d="M7 3h10v6a5 5 0 0 1-10 0V3z" fill={color}/><path d="M5 4H2v2a4 4 0 0 0 4 4M19 4h3v2a4 4 0 0 1-4 4" {...line}/><rect x="10" y="15" width="4" height="3" fill={color}/><rect x="7" y="19" width="10" height="2" rx="1" fill={color}/></svg>;
  if(name==='rocket')return <svg {...common}><path d="M12 2c3 1 5 5 5 9 0 2-1 4-2 5l-3 3-3-3c-1-1-2-3-2-5 0-4 2-8 5-9z" fill={color}/><circle cx="12" cy="9" r="2" fill="#fff" opacity=".55"/></svg>;
  if(name==='fire')return <svg {...common}><path d="M12 2c3 4 5 7 5 10.2A5 5 0 0 1 12 18a5 5 0 0 1-5-5.8c0-1 .3-2 1-3 .4 1.8 1.2 2.6 2.2 2.2.8-2-.4-4.2.6-6.3.3-.8.7-1.8 1.2-3.1z" fill={color}/></svg>;
  if(name==='thumbsUp')return <svg {...common}><path d="M2 11h3v10H2V11zM7 21h9.5a2 2 0 0 0 1.9-1.4l2-6A2 2 0 0 0 18.5 11H14l.8-4.3a2 2 0 0 0-3.6-1.5L7 11v10z" fill={color}/></svg>;
  return <svg {...common}><rect x="4" y="12" width="3.5" height="8" rx="1" fill={color}/><rect x="10.3" y="7" width="3.5" height="13" rx="1" fill={color}/><rect x="16.6" y="3" width="3.5" height="17" rx="1" fill={color}/></svg>;
}

function VText({scene,kind,id,children,baseStyle={},editorMode,selected,onSelect}){
  const edit=scene.visualText?.[kind]?.[id]||{};
  const bound=scene.visualBindings?.[id];
  const content=edit.text??bound??children;
  const style={...baseStyle,fontFamily:edit.fontKey?fontFor(edit.fontKey):baseStyle.fontFamily,color:edit.color||baseStyle.color,fontSize:edit.fontSize||baseStyle.fontSize,textAlign:edit.align||baseStyle.textAlign||'center',WebkitTextStroke:Number(edit.strokeWidth||0)?`${Number(edit.strokeWidth)}px ${edit.strokeColor||'#000'}`:'0 transparent',transform:`translate3d(${Number(edit.x)||0}px,${Number(edit.y)||0}px,0)`,display:baseStyle.display||'block',cursor:editorMode?'pointer':'default',outline:editorMode&&selected?'4px solid rgba(255,255,255,.78)':'none',outlineOffset:5,borderRadius:6,overflowWrap:'normal',wordBreak:'keep-all'};
  return <div onClick={editorMode?(e)=>{e.stopPropagation();onSelect?.(id)}:undefined} style={style}>{content}</div>;
}

function Frame({children,scene,width=420,padding=28,style={}}){const dark=luminance(scene.bg)<.45;return <div style={{width,padding,borderRadius:22,background:dark?rgba(scene.fg,.055):rgba(scene.fg,.035),border:`1px solid ${rgba(scene.fg,dark?.13:.09)}`,boxShadow:`0 18px 34px ${rgba('#000',dark?.34:.13)}`,...style}}>{children}</div>}
function Chip({children,scene,accent=false,style={}}){const bg=accent?scene.accent:rgba(scene.fg,.08);const color=accent?inkOn(scene.accent,scene.accent2):scene.fg;return <div style={{display:'inline-flex',alignItems:'center',gap:8,padding:'7px 13px',borderRadius:999,background:bg,color,font:`700 20px ${FONTS.body}`,...style}}>{children}</div>}
function NegationOverlay({scene}){if(scene.visualState!=='negative')return null;return <div style={{position:'absolute',inset:'8%',pointerEvents:'none'}}><div style={{position:'absolute',left:'4%',right:'4%',top:'50%',height:13,borderRadius:20,background:'#D83A35',transform:'rotate(-10deg)',boxShadow:'0 6px 15px rgba(0,0,0,.16)'}}/></div>}

function Ring({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){
  const frame=useCurrentFrame(),{durationInFrames}=useVideoConfig();const p=pathProgress(frame,durationInFrames,.04,.62);const raw=scene.visualBindings?.percent||scene.visualBindings?.value||'';const n=numberFromText(raw);const pct=n!=null?Math.max(0,Math.min(100,n)):Math.round(72*p);const showNumber=n!=null;const r=118,c=2*Math.PI*r;
  return <div style={{width:340,height:380,position:'relative',display:'grid',placeItems:'center'}}><svg width="340" height="340" viewBox="0 0 340 340" style={{transform:'rotate(-90deg)'}}><circle cx="170" cy="170" r={r} fill="none" stroke={rgba(scene.fg,.13)} strokeWidth="24"/><circle cx="170" cy="170" r={r} fill="none" stroke={scene.accent} strokeWidth="24" strokeLinecap="round" strokeDasharray={c} strokeDashoffset={c*(1-(showNumber?p*(pct/100):p*.78))}/></svg><div style={{position:'absolute',top:125,left:0,right:0,textAlign:'center'}}><VText scene={scene} kind={kind} id="value" editorMode={editorMode} selected={selectedTextKey==='value'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.mono,fontWeight:800,fontSize:showNumber?68:48,color:scene.fg,lineHeight:1}}>{showNumber?`${Math.round(pct*p)}%`:'◔'}</VText><VText scene={scene} kind={kind} id="label" editorMode={editorMode} selected={selectedTextKey==='label'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.bold,fontWeight:800,fontSize:28,color:scene.fg,marginTop:14}}>{meta.fields?.[0]?.text||meta.label}</VText></div><NegationOverlay scene={scene}/></div>
}

function AppCard({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){
  const frame=useCurrentFrame(),{fps,durationInFrames}=useVideoConfig();
  const s=enter(frame,fps,0),op=fadeOut(frame,durationInFrames),platform=kind;
  const brand=platform==='youtube'?'#E62117':platform==='whatsapp'?'#25D366':'#D9467B';
  const fields=Object.fromEntries((getVisualMeta(kind)?.fields||[]).map(f=>[f.key,f]));
  if(platform==='whatsapp'){
    const statusDefault='online',timeDefault='10:41';
    return <div style={{width:430,padding:24,borderRadius:28,background:luminance(scene.bg)<.5?'#17242B':'#EEF2F4',boxShadow:'0 24px 44px rgba(0,0,0,.18)',opacity:op,transform:`scale(${.92+.08*s})`}}>
      <div style={{display:'flex',alignItems:'center',gap:14,paddingBottom:18,borderBottom:`1px solid ${rgba(scene.fg,.1)}`}}>
        <div style={{width:48,height:48,borderRadius:'50%',background:scene.accent}}/>
        <div>
          <VText scene={scene} kind={kind} id="title" editorMode={editorMode} selected={selectedTextKey==='title'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.bold,fontWeight:800,fontSize:26,color:scene.fg,textAlign:'left'}}>{fields.title?.text||'WhatsApp'}</VText>
          <VText scene={scene} kind={kind} id="status" editorMode={editorMode} selected={selectedTextKey==='status'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:600,fontSize:17,color:brand,textAlign:'left'}}>{statusDefault}</VText>
        </div>
      </div>
      <div style={{marginTop:24,background:luminance(scene.bg)<.5?'#24343D':'#fff',borderRadius:'20px 20px 20px 5px',padding:'18px 20px',color:scene.fg,maxWidth:'88%'}}>
        <VText scene={scene} kind={kind} id="message" editorMode={editorMode} selected={selectedTextKey==='message'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:650,fontSize:24,color:scene.fg,textAlign:'left',lineHeight:1.25}}>{fields.message?.text||scene.visualBindings?.message||'TAP → REPLY'}</VText>
        <div style={{display:'flex',justifyContent:'flex-end',alignItems:'center',gap:8,marginTop:10}}>
          <VText scene={scene} kind={kind} id="time" editorMode={editorMode} selected={selectedTextKey==='time'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:500,fontSize:14,color:scene.muted,textAlign:'right'}}>{timeDefault}</VText>
          <span style={{font:`700 14px ${FONTS.body}`,color:'#53BDEB'}}>✓✓</span>
        </div>
      </div>
    </div>;
  }
  if(platform==='youtube'){
    const duration=scene.semantic?.data?.durations?.[0]||'';
    return <div style={{width:440,opacity:op,transform:`translateY(${(1-s)*28}px)`}}>
      <div style={{aspectRatio:'16/9',borderRadius:24,background:`linear-gradient(135deg,${scene.accent},${rgba(scene.accent2,.8)})`,display:'grid',placeItems:'center',position:'relative',overflow:'hidden',boxShadow:'0 22px 42px rgba(0,0,0,.18)'}}>
        <div style={{width:78,height:78,borderRadius:'50%',background:'#fff',display:'grid',placeItems:'center'}}><Icon name="play" color={brand} size={38}/></div>
        {duration?<div style={{position:'absolute',bottom:14,right:14,padding:'5px 10px',borderRadius:7,background:'rgba(0,0,0,.72)'}}><VText scene={scene} kind={kind} id="duration" editorMode={editorMode} selected={selectedTextKey==='duration'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:700,fontSize:16,color:'#fff'}}>{duration}</VText></div>:null}
      </div>
      <div style={{display:'flex',gap:14,alignItems:'center',marginTop:18}}><div style={{width:50,height:50,borderRadius:'50%',background:scene.accent}}/><div style={{flex:1,textAlign:'left'}}>
        <VText scene={scene} kind={kind} id="title" editorMode={editorMode} selected={selectedTextKey==='title'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.bold,fontWeight:800,fontSize:25,color:scene.fg,textAlign:'left'}}>{fields.title?.text||'YOUTUBE'}</VText>
        <VText scene={scene} kind={kind} id="subtitle" editorMode={editorMode} selected={selectedTextKey==='subtitle'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:550,fontSize:18,color:scene.muted,textAlign:'left'}}>{fields.subtitle?.text||'Creator Studio'}</VText>
      </div></div>
      <div style={{marginTop:14}}><VText scene={scene} kind={kind} id="footer" editorMode={editorMode} selected={selectedTextKey==='footer'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.bold,fontWeight:800,fontSize:18,color:brand,textAlign:'left'}}>{fields.footer?.text||'UPLOAD • WATCH • GROW'}</VText></div>
    </div>;
  }
  return <div style={{width:355,height:550,borderRadius:32,overflow:'hidden',position:'relative',background:`linear-gradient(160deg,${scene.accent2},${scene.accent})`,boxShadow:'0 24px 46px rgba(0,0,0,.2)',opacity:op,transform:`scale(${.94+.06*s})`}}>
    <div style={{position:'absolute',right:18,bottom:110,display:'flex',flexDirection:'column',gap:26,color:'#fff'}}><Icon name="heart" color="#fff" size={34}/><Icon name="comment" color="#fff" size={34}/><Icon name="share" color="#fff" size={34}/></div>
    <div style={{position:'absolute',left:0,right:0,bottom:0,padding:'70px 24px 24px',background:'linear-gradient(0deg,rgba(0,0,0,.65),transparent)'}}>
      <VText scene={scene} kind={kind} id="title" editorMode={editorMode} selected={selectedTextKey==='title'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.bold,fontWeight:800,fontSize:30,color:'#fff',textAlign:'left'}}>{fields.title?.text||'REEL'}</VText>
      <VText scene={scene} kind={kind} id="subtitle" editorMode={editorMode} selected={selectedTextKey==='subtitle'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:550,fontSize:20,color:'rgba(255,255,255,.88)',textAlign:'left',marginTop:7}}>{fields.subtitle?.text||'creative card'}</VText>
    </div>
  </div>;
}

function StatSingle({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){
  const frame=useCurrentFrame(),{fps,durationInFrames}=useVideoConfig();const s=enter(frame,fps),op=fadeOut(frame,durationInFrames);const value=scene.visualBindings?.value||meta.fields?.find(f=>f.key==='value')?.text||'';const showValue=Boolean(scene.visualBindings?.value)||!meta.requiresRealData;
  return <div style={{position:'relative'}}><Frame scene={scene} width={430} style={{opacity:op,transform:`scale(${.9+.1*s})`}}><div style={{display:'flex',gap:12,alignItems:'center'}}><div style={{width:46,height:46,borderRadius:12,background:rgba(scene.accent,.14),display:'grid',placeItems:'center'}}><Icon name={meta.iconName||'chart'} color={scene.accent} size={26}/></div><VText scene={scene} kind={kind} id="label" editorMode={editorMode} selected={selectedTextKey==='label'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:750,fontSize:22,color:scene.muted,textAlign:'left',letterSpacing:1}}>{meta.fields?.find(f=>f.key==='label')?.text||meta.label}</VText></div><div style={{marginTop:18}}><VText scene={scene} kind={kind} id="value" editorMode={editorMode} selected={selectedTextKey==='value'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.mono,fontWeight:900,fontSize:68,color:scene.fg,textAlign:'left',lineHeight:.95}}>{showValue?value:'—'}</VText></div><div style={{height:6,borderRadius:99,background:rgba(scene.fg,.1),marginTop:24,overflow:'hidden'}}><div style={{height:'100%',width:`${Math.round(pathProgress(frame,durationInFrames)*78)}%`,background:scene.accent}}/></div></Frame><NegationOverlay scene={scene}/></div>
}

function Charts({scene,kind,meta,variant,editorMode,selectedTextKey,onSelectText}){
  const frame=useCurrentFrame(),{fps,durationInFrames}=useVideoConfig();const s=enter(frame,fps),p=pathProgress(frame,durationInFrames,.08,.62);const title=meta.fields?.find(f=>f.key==='title')?.text||meta.label;const value=scene.visualBindings?.value||scene.visualBindings?.percent||scene.semantic?.data?.primary||'';
  if(variant==='pie') {const r=85,c=2*Math.PI*r;const n=numberFromText(value);const pct=n!=null?Math.max(1,Math.min(99,n)):62;return <div style={{display:'grid',placeItems:'center',transform:`scale(${.9+.1*s})`}}><svg width="260" height="260" viewBox="0 0 260 260" style={{transform:'rotate(-90deg)'}}><circle cx="130" cy="130" r={r} fill="none" stroke={rgba(scene.fg,.1)} strokeWidth="30"/><circle cx="130" cy="130" r={r} fill="none" stroke={scene.accent} strokeWidth="30" strokeLinecap="round" strokeDasharray={c} strokeDashoffset={c*(1-p*pct/100)}/></svg><div style={{position:'absolute',font:`900 48px ${FONTS.mono}`,color:scene.fg}}>{n!=null?`${Math.round(pct*p)}%`:'DATA'}</div></div>}
  if(variant==='line') return <Frame scene={scene} width={450}><VText scene={scene} kind={kind} id="title" editorMode={editorMode} selected={selectedTextKey==='title'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:750,fontSize:22,color:scene.fg,textAlign:'left'}}>{title}</VText><svg viewBox="0 0 360 180" width="100%" height="220" style={{marginTop:10,overflow:'visible'}}><path d="M10 150 L72 116 L138 126 L208 68 L280 88 L350 28" fill="none" stroke={scene.accent} strokeWidth="8" strokeLinecap="round" strokeLinejoin="round" pathLength="1" strokeDasharray="1" strokeDashoffset={1-p}/><path d="M10 150 L72 116 L138 126 L208 68 L280 88 L350 28 L350 170 L10 170Z" fill={rgba(scene.accent,.12)} opacity={p}/></svg>{value?<Chip scene={scene} accent style={{fontFamily:FONTS.mono}}>{value}</Chip>:null}</Frame>;
  const heights=[.34,.55,.44,.72,.86];return <Frame scene={scene} width={450}><VText scene={scene} kind={kind} id="title" editorMode={editorMode} selected={selectedTextKey==='title'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:750,fontSize:22,color:scene.fg,textAlign:'left'}}>{title}</VText><div style={{height:220,display:'flex',alignItems:'flex-end',gap:18,marginTop:18,borderBottom:`2px solid ${rgba(scene.fg,.16)}`}}>{heights.map((h,i)=><div key={i} style={{flex:1,height:`${Math.max(4,h*p*100)}%`,borderRadius:'10px 10px 2px 2px',background:i===heights.length-1?scene.accent:rgba(scene.accent,.4)}}/>)}</div>{value?<div style={{marginTop:14,font:`800 28px ${FONTS.mono}`,color:scene.fg,textAlign:'left'}}>{value}</div>:null}</Frame>;
}

function ProgressBarVisual({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{durationInFrames}=useVideoConfig();const p=pathProgress(frame,durationInFrames,.05,.55);const raw=scene.visualBindings?.value||scene.visualBindings?.percent||'';const n=numberFromText(raw);const pct=n!=null?Math.max(0,Math.min(100,n)):82;return <Frame scene={scene} width={440}><div style={{display:'flex',alignItems:'center',justifyContent:'space-between',gap:20}}><VText scene={scene} kind={kind} id="label" editorMode={editorMode} selected={selectedTextKey==='label'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:750,fontSize:22,color:scene.fg,textAlign:'left'}}>{meta.fields?.[0]?.text||meta.label}</VText><VText scene={scene} kind={kind} id="value" editorMode={editorMode} selected={selectedTextKey==='value'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.mono,fontWeight:900,fontSize:30,color:scene.accent}}>{n!=null?`${Math.round(pct*p)}%`:''}</VText></div><div style={{height:22,borderRadius:99,background:rgba(scene.fg,.1),overflow:'hidden',marginTop:20}}><div style={{width:`${p*(n!=null?pct:75)}%`,height:'100%',background:scene.accent,borderRadius:99}}/></div></Frame>}

function CounterVisual({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{durationInFrames}=useVideoConfig();const p=pathProgress(frame,durationInFrames,.04,.5);const raw=scene.visualBindings?.value||scene.semantic?.data?.primary||'';const n=numberFromText(raw);const suffix=raw&&n!=null?String(raw).replace(String(n),'').trim():meta.suffix||'';const prefix=raw?.trim().startsWith('₹')?'₹':meta.prefix||'';const shown=n!=null?`${prefix}${Math.round(n*p).toLocaleString('en-IN')}${suffix}`:'+';return <div style={{textAlign:'center'}}><div style={{width:78,height:78,borderRadius:20,margin:'0 auto 18px',background:rgba(scene.accent,.14),display:'grid',placeItems:'center'}}><Icon name={meta.iconName||'trend'} color={scene.accent} size={40}/></div><VText scene={scene} kind={kind} id="value" editorMode={editorMode} selected={selectedTextKey==='value'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.mono,fontWeight:900,fontSize:78,color:scene.fg,lineHeight:.95}}>{shown}</VText><VText scene={scene} kind={kind} id="label" editorMode={editorMode} selected={selectedTextKey==='label'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:750,fontSize:24,color:scene.muted,marginTop:16}}>{meta.fields?.find(f=>f.key==='label')?.text||meta.label}</VText></div>}

function GridVisual({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{fps}=useVideoConfig();const fields=meta.fields||[];return <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:14,width:430}}>{fields.slice(0,4).map((f,i)=>{const s=enter(frame,fps,i*2);const safeDefault=meta.requiresRealData?(scene.visualBindings?.[f.key]??(i===0&&scene.semantic?.data?.primary?scene.semantic.data.primary:'—')):f.text;return <div key={f.key} style={{padding:'28px 16px',borderRadius:16,background:i===0?scene.accent:rgba(scene.fg,.055),border:`1px solid ${rgba(scene.fg,.1)}`,transform:`scale(${.82+.18*s})`,opacity:s}}><VText scene={scene} kind={kind} id={f.key} editorMode={editorMode} selected={selectedTextKey===f.key} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.bold,fontWeight:800,fontSize:26,color:i===0?inkOn(scene.accent,scene.accent2):scene.fg,textAlign:'center'}}>{safeDefault}</VText></div>})}</div>}

function Checklist({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{fps}=useVideoConfig();return <Frame scene={scene} width={430}>{(meta.fields||[]).slice(0,4).map((f,i)=>{const s=enter(frame,fps,i*3);return <div key={f.key} style={{display:'flex',alignItems:'center',gap:16,padding:'12px 0',opacity:s,transform:`translateX(${(1-s)*22}px)`,borderBottom:i<meta.fields.length-1?`1px solid ${rgba(scene.fg,.08)}`:'none'}}><div style={{width:34,height:34,borderRadius:'50%',background:scene.accent,display:'grid',placeItems:'center',flex:'0 0 auto'}}><Icon name="check" color={inkOn(scene.accent,scene.accent2)} size={18}/></div><VText scene={scene} kind={kind} id={f.key} editorMode={editorMode} selected={selectedTextKey===f.key} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:650,fontSize:24,color:scene.fg,textAlign:'left'}}>{f.text}</VText></div>})}</Frame>}

function Compare({scene,kind,meta,split=false,editorMode,selectedTextKey,onSelectText}){const fields=meta.fields||[];const left=fields[0],right=fields[1];return <div style={{display:'grid',gridTemplateColumns:split?'1fr 1fr':'1fr',gap:16,width:440}}>{[left,right].filter(Boolean).map((f,i)=><div key={f.key} style={{display:'flex',alignItems:'center',gap:14,padding:20,borderRadius:16,background:i===0?rgba('#C0392B',.12):rgba('#1E8E5A',.13),border:`1px solid ${i===0?rgba('#C0392B',.28):rgba('#1E8E5A',.28)}`}}><div style={{width:36,height:36,borderRadius:'50%',background:i===0?'#C0392B':'#1E8E5A',display:'grid',placeItems:'center'}}><Icon name={i===0?'cross':'check'} color="#fff" size={20}/></div><VText scene={scene} kind={kind} id={f.key} editorMode={editorMode} selected={selectedTextKey===f.key} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:700,fontSize:23,color:scene.fg,textAlign:'left',flex:1}}>{f.text}</VText></div>)}</div>}

function Offer({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const fields=Object.fromEntries((meta.fields||[]).map(f=>[f.key,f]));const ink=inkOn(scene.accent,scene.accent2);return <Frame scene={scene} width={440} style={{position:'relative',overflow:'hidden'}}><div style={{position:'absolute',top:18,right:-42,transform:'rotate(38deg)',padding:'8px 48px',background:scene.accent,color:ink,font:`800 16px ${FONTS.body}`}}><VText scene={scene} kind={kind} id="badge" editorMode={editorMode} selected={selectedTextKey==='badge'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:800,fontSize:16,color:ink}}>{fields.badge?.text||'DEAL'}</VText></div><VText scene={scene} kind={kind} id="label" editorMode={editorMode} selected={selectedTextKey==='label'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:750,fontSize:20,color:scene.muted,textAlign:'left',letterSpacing:1}}>{fields.label?.text||meta.label}</VText><div style={{marginTop:20}}><VText scene={scene} kind={kind} id="was" editorMode={editorMode} selected={selectedTextKey==='was'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:550,fontSize:24,color:scene.muted,textAlign:'left',textDecoration:'line-through'}}>{meta.requiresRealData&&!scene.visualBindings?.was?'':(fields.was?.text||'')}</VText><VText scene={scene} kind={kind} id="now" editorMode={editorMode} selected={selectedTextKey==='now'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.mono,fontWeight:900,fontSize:62,color:scene.accent,textAlign:'left',marginTop:5}}>{meta.requiresRealData&&!scene.visualBindings?.now?'—':(scene.visualBindings?.now||fields.now?.text||'—')}</VText></div></Frame>}

function Quote({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const fields=Object.fromEntries((meta.fields||[]).map(f=>[f.key,f]));return <div style={{width:440,borderTop:`3px solid ${scene.accent}`,paddingTop:24,textAlign:'left'}}><div style={{font:`600 42px ${FONTS.editorial}`,color:rgba(scene.accent,.35),lineHeight:.5}}>“</div><VText scene={scene} kind={kind} id="quote" editorMode={editorMode} selected={selectedTextKey==='quote'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.editorial,fontStyle:'italic',fontWeight:600,fontSize:32,color:scene.fg,textAlign:'left',lineHeight:1.2}}>{fields.quote?.text||scene.visualBindings?.quote||'KEY IDEA'}</VText><VText scene={scene} kind={kind} id="author" editorMode={editorMode} selected={selectedTextKey==='author'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:750,fontSize:17,color:scene.muted,textAlign:'left',marginTop:22,letterSpacing:1}}>{meta.requiresRealData&&!scene.visualBindings?.author?'':(fields.author?.text||'')}</VText></div>}

function Timeline({scene,kind,meta,horizontal=false,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{durationInFrames}=useVideoConfig();const p=pathProgress(frame,durationInFrames,.05,.7);const fields=(meta.fields||[]).slice(0,4);if(horizontal)return <div style={{width:460}}><div style={{position:'relative',display:'flex',justifyContent:'space-between'}}><div style={{position:'absolute',left:28,right:28,top:24,height:4,background:rgba(scene.fg,.12)}}/><div style={{position:'absolute',left:28,top:24,height:4,width:`${p*87}%`,background:scene.accent}}/>{fields.map((f,i)=><div key={f.key} style={{width:94,position:'relative',textAlign:'center'}}><div style={{width:48,height:48,borderRadius:'50%',margin:'0 auto',background:p>i/(fields.length-1||1)?scene.accent:rgba(scene.fg,.13),display:'grid',placeItems:'center',color:p>i/(fields.length-1||1)?inkOn(scene.accent,scene.accent2):scene.fg,font:`800 20px ${FONTS.mono}`}}>{i+1}</div><VText scene={scene} kind={kind} id={f.key} editorMode={editorMode} selected={selectedTextKey===f.key} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:650,fontSize:17,color:scene.fg,marginTop:12}}>{f.text}</VText></div>)}</div></div>;
  return <div style={{width:420,position:'relative'}}><div style={{position:'absolute',left:23,top:24,bottom:24,width:4,background:rgba(scene.fg,.12)}}/><div style={{position:'absolute',left:23,top:24,width:4,height:`${p*85}%`,background:scene.accent}}/>{fields.map((f,i)=><div key={f.key} style={{display:'flex',alignItems:'center',gap:18,margin:'18px 0',position:'relative'}}><div style={{width:50,height:50,borderRadius:'50%',background:p>i/(fields.length-1||1)?scene.accent:rgba(scene.fg,.13),display:'grid',placeItems:'center',color:p>i/(fields.length-1||1)?inkOn(scene.accent,scene.accent2):scene.fg,font:`800 20px ${FONTS.mono}`,zIndex:2}}>{i+1}</div><div style={{flex:1,padding:'13px 16px',borderRadius:12,border:`1px solid ${rgba(scene.fg,.1)}`}}><VText scene={scene} kind={kind} id={f.key} editorMode={editorMode} selected={selectedTextKey===f.key} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:650,fontSize:21,color:scene.fg,textAlign:'left'}}>{f.text}</VText></div></div>)}</div>}

function Device({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const isBrowser=meta.deviceShape==='browser';const isWatch=meta.deviceShape==='watch';const w=isBrowser?420:isWatch?190:meta.deviceShape==='tablet'?290:330;const h=isBrowser?260:isWatch?220:meta.deviceShape==='tablet'?430:520;return <div style={{textAlign:'center'}}><div style={{width:w,height:h,borderRadius:isBrowser?20:isWatch?48:42,background:'#1D2026',padding:isBrowser?12:14,boxShadow:'0 30px 52px rgba(0,0,0,.28)',position:'relative',overflow:'hidden'}}>{isBrowser?<div style={{height:38,borderRadius:12,background:'#2A2E36',display:'flex',gap:9,alignItems:'center',padding:'0 14px'}}>{['#FF5F57','#FEBC2E','#28C840'].map(c=><span key={c} style={{width:10,height:10,borderRadius:'50%',background:c}}/>)}<div style={{height:16,flex:1,borderRadius:8,background:'rgba(255,255,255,.08)',marginLeft:10}}/></div>:null}<div style={{position:'absolute',left:14,right:14,top:isBrowser?62:14,bottom:14,borderRadius:isBrowser?12:isWatch?36:30,background:scene.bg,padding:22}}><div style={{height:10,width:'58%',borderRadius:8,background:rgba(scene.fg,.16)}}/><div style={{height:10,width:'40%',borderRadius:8,background:rgba(scene.fg,.1),marginTop:10}}/><div style={{height:isWatch?70:115,borderRadius:16,background:scene.accent,marginTop:22}}/></div></div><VText scene={scene} kind={kind} id="caption" editorMode={editorMode} selected={selectedTextKey==='caption'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:650,fontSize:21,color:scene.muted,marginTop:20}}>{meta.fields?.[0]?.text||meta.label}</VText></div>}

function SocialPost({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){
  const fields=Object.fromEntries((meta.fields||[]).map(f=>[f.key,f]));const brand=meta.platformColor||scene.accent;
  return <Frame scene={scene} width={460}>
    <div style={{display:'flex',alignItems:'center',gap:14}}>
      <div style={{width:52,height:52,borderRadius:'50%',background:scene.accent}}/>
      <div style={{flex:1}}>
        <VText scene={scene} kind={kind} id="handle" editorMode={editorMode} selected={selectedTextKey==='handle'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.bold,fontWeight:800,fontSize:22,color:scene.fg,textAlign:'left'}}>{meta.requiresRealData?'@creator':(fields.handle?.text||'@creator')}</VText>
        <VText scene={scene} kind={kind} id="time" editorMode={editorMode} selected={selectedTextKey==='time'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:500,fontSize:15,color:scene.muted,textAlign:'left'}}>2h ago</VText>
      </div>
      <div style={{width:42,height:42,borderRadius:12,background:rgba(brand,.12),display:'grid',placeItems:'center'}}><Icon name={meta.iconName||'send'} color={brand} size={24}/></div>
    </div>
    <VText scene={scene} kind={kind} id="text" editorMode={editorMode} selected={selectedTextKey==='text'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:550,fontSize:24,color:scene.fg,textAlign:'left',lineHeight:1.3,marginTop:24}}>{fields.text?.text||scene.visualBindings?.text||'ACTION → RESULT'}</VText>
    <div style={{display:'flex',gap:26,marginTop:24,color:scene.muted}}><Icon name="heart" color={scene.muted}/><Icon name="comment" color={scene.muted}/><Icon name="share" color={scene.muted}/></div>
  </Frame>;
}

function Badge({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{fps}=useVideoConfig();const s=enter(frame,fps);return <div style={{width:250,height:250,borderRadius:'50%',padding:13,background:`conic-gradient(${scene.accent},${scene.accent2},${scene.accent})`,transform:`rotate(${(1-s)*-14}deg) scale(${.65+.35*s})`,boxShadow:'0 24px 42px rgba(0,0,0,.2)'}}><div style={{width:'100%',height:'100%',borderRadius:'50%',background:scene.bg,display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',gap:10}}><Icon name={meta.badgeIcon||'shield'} color={scene.accent} size={48}/><VText scene={scene} kind={kind} id="text" editorMode={editorMode} selected={selectedTextKey==='text'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.bold,fontWeight:900,fontSize:28,color:scene.fg,maxWidth:180}}>{meta.fields?.[0]?.text||meta.label}</VText></div></div>}

function Reaction({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{fps}=useVideoConfig();const s=enter(frame,fps),ink=inkOn(scene.accent,scene.accent2);const icon=meta.iconName||'star';const field=meta.fields?.find(f=>['caption','label','text'].includes(f.key))||meta.fields?.[0];const fieldId=field?.key||'caption';return <div style={{display:'flex',flexDirection:'column',alignItems:'center'}}><div style={{width:130,height:130,borderRadius:'50%',background:scene.accent,display:'grid',placeItems:'center',transform:`scale(${.55+.45*s})`,boxShadow:'0 14px 30px rgba(0,0,0,.16)'}}><Icon name={icon} color={ink} size={64}/></div><div style={{marginTop:22}}><VText scene={scene} kind={kind} id={fieldId} editorMode={editorMode} selected={selectedTextKey===fieldId} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.bold,fontWeight:800,fontSize:28,color:scene.fg}}>{field?.text||meta.label}</VText></div></div>}

function MapVisual({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{fps}=useVideoConfig();const s=enter(frame,fps);return <div style={{width:460}}><div style={{height:260,borderRadius:24,background:luminance(scene.bg)<.5?'#27303A':'#E9ECEB',position:'relative',overflow:'hidden'}}><svg width="100%" height="100%" viewBox="0 0 460 260"><path d="M0 60 C100 145 200 20 460 95" fill="none" stroke={rgba(scene.muted,.55)} strokeWidth="5"/><path d="M50 0 C90 90 60 160 150 260" fill="none" stroke={rgba(scene.muted,.45)} strokeWidth="4"/></svg><div style={{position:'absolute',left:'50%',top:'52%',transform:`translate(-50%,-100%) translateY(${(1-s)*-80}px)`}}><Icon name="pin" color={scene.accent} size={82}/></div></div><div style={{marginTop:16}}><VText scene={scene} kind={kind} id="label" editorMode={editorMode} selected={selectedTextKey==='label'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.bold,fontWeight:800,fontSize:26,color:scene.fg}}>{scene.visualBindings?.label||(meta.requiresRealData?'LOCATION':(meta.fields?.[0]?.text||'LOCATION'))}</VText></div></div>}

function BeforeAfter({scene}){const frame=useCurrentFrame(),{durationInFrames}=useVideoConfig();const p=pathProgress(frame,durationInFrames,.05,.65);return <div style={{width:470,height:360,borderRadius:24,overflow:'hidden',position:'relative',background:rgba(scene.fg,.08),boxShadow:'0 20px 40px rgba(0,0,0,.16)'}}><div style={{position:'absolute',inset:0,display:'grid',placeItems:'center',font:`800 34px ${FONTS.bold}`,color:scene.fg}}>BEFORE</div><div style={{position:'absolute',left:0,top:0,bottom:0,width:`${p*100}%`,overflow:'hidden',background:scene.accent,color:inkOn(scene.accent,scene.accent2),display:'grid',placeItems:'center',font:`800 34px ${FONTS.bold}`}}>AFTER</div><div style={{position:'absolute',top:0,bottom:0,left:`${p*100}%`,width:5,background:'#fff',boxShadow:'0 0 14px rgba(0,0,0,.2)'}}/></div>}

function QR({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const cells=[];for(let r=0;r<9;r++)for(let c=0;c<9;c++){const on=(r<2&&c<2)||(r<2&&c>6)||(r>6&&c<2)||((r*7+c*13+r*c)%3===0);if(on)cells.push(<rect key={`${r}-${c}`} x={c} y={r} width=".9" height=".9" rx=".12" fill={scene.fg}/>)}return <div style={{textAlign:'center'}}><div style={{padding:24,borderRadius:20,background:scene.bg,border:`2px solid ${rgba(scene.fg,.12)}`,display:'inline-block'}}><svg width="230" height="230" viewBox="0 0 9 9">{cells}</svg></div><VText scene={scene} kind={kind} id="caption" editorMode={editorMode} selected={selectedTextKey==='caption'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:700,fontSize:22,color:scene.fg,marginTop:18}}>{meta.fields?.[0]?.text||'Scan to open'}</VText></div>}

function StarRating({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const bound=scene.visualBindings?.value||scene.semantic?.data?.primary||'';const hasReal=Boolean(bound)||!meta.requiresRealData;const value=hasReal?(bound||meta.fields?.[0]?.text||'—'):'—';return <div style={{textAlign:'center'}}><VText scene={scene} kind={kind} id="value" editorMode={editorMode} selected={selectedTextKey==='value'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.mono,fontWeight:900,fontSize:78,color:scene.fg}}>{value}</VText><div style={{display:'flex',gap:8,justifyContent:'center',marginTop:8,opacity:hasReal?1:.28}}>{[0,1,2,3,4].map(i=><Icon key={i} name="star" color={hasReal?'#E2B43A':scene.muted} size={36}/>)}</div><VText scene={scene} kind={kind} id="sub" editorMode={editorMode} selected={selectedTextKey==='sub'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:600,fontSize:20,color:scene.muted,marginTop:16}}>{hasReal?(meta.fields?.[1]?.text||''):''}</VText></div>}

function Confetti({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{durationInFrames}=useVideoConfig();const p=pathProgress(frame,durationInFrames,.02,.5);const pieces=Array.from({length:18},(_,i)=>{const a=(i/18)*Math.PI*2;const d=35+(i%5)*22;const x=Math.cos(a)*d*p,y=Math.sin(a)*d*p;return <div key={i} style={{position:'absolute',left:'50%',top:'45%',width:10+(i%3)*4,height:22,background:i%2?scene.accent:scene.accent2,transform:`translate(${x}px,${y}px) rotate(${i*37*p}deg)`,opacity:1-p*.25,borderRadius:3}}/>});return <div style={{width:430,height:350,position:'relative'}}>{pieces}<div style={{position:'absolute',left:0,right:0,top:'42%',textAlign:'center'}}><VText scene={scene} kind={kind} id="caption" editorMode={editorMode} selected={selectedTextKey==='caption'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.impact,fontWeight:900,fontSize:58,color:scene.fg}}>{meta.fields?.[0]?.text||'CELEBRATE'}</VText></div></div>}

function Product({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const fields=Object.fromEntries((meta.fields||[]).map(f=>[f.key,f]));return <Frame scene={scene} width={440}><div style={{height:180,borderRadius:18,background:scene.accent,position:'relative',overflow:'hidden'}}><div style={{position:'absolute',left:'18%',right:'18%',bottom:0,top:'28%',borderRadius:'22px 22px 0 0',background:rgba(inkOn(scene.accent,scene.accent2),.16)}}/></div><VText scene={scene} kind={kind} id="title" editorMode={editorMode} selected={selectedTextKey==='title'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.bold,fontWeight:800,fontSize:30,color:scene.fg,textAlign:'left',marginTop:18}}>{fields.title?.text||meta.label}</VText><VText scene={scene} kind={kind} id="tag" editorMode={editorMode} selected={selectedTextKey==='tag'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:750,fontSize:18,color:scene.accent,textAlign:'left',marginTop:7}}>{fields.tag?.text||''}</VText></Frame>}

function Hook({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{fps}=useVideoConfig();const s=enter(frame,fps);return <div style={{width:450,textAlign:'left'}}><Chip scene={scene} style={{fontSize:16,letterSpacing:2}}>HOOK</Chip><div style={{marginTop:20,transform:`translateY(${(1-s)*24}px)`,opacity:s}}><VText scene={scene} kind={kind} id="headline" editorMode={editorMode} selected={selectedTextKey==='headline'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.impact,fontWeight:900,fontSize:62,color:scene.fg,textAlign:'left',lineHeight:.95}}>{scene.visualBindings?.headline||meta.fields?.[0]?.text||'STOP → WATCH'}</VText></div><div style={{height:7,width:`${s*150}px`,borderRadius:8,background:scene.accent,marginTop:20}}/></div>}


function StackVisual({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{fps}=useVideoConfig();const s=enter(frame,fps);const field=meta.fields?.[0];return <div style={{width:390,height:300,position:'relative'}}>{[2,1,0].map((n,i)=><div key={n} style={{position:'absolute',left:35+n*28,top:35+n*20,width:310,height:190,borderRadius:20,background:n===0?scene.accent:rgba(scene.fg,n===1?.09:.05),border:`1px solid ${rgba(scene.fg,.12)}`,transform:`rotate(${(n-1)*4*s}deg) translateY(${(1-s)*18}px)`,boxShadow:n===0?'0 20px 38px rgba(0,0,0,.16)':'none'}}/>)}<div style={{position:'absolute',left:0,right:0,top:120,textAlign:'center'}}><VText scene={scene} kind={kind} id={field?.key||'title'} editorMode={editorMode} selected={selectedTextKey===(field?.key||'title')} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.bold,fontWeight:900,fontSize:50,color:inkOn(scene.accent,scene.accent2)}}>{field?.text||'CONTENT'}</VText></div></div>}

function CTAVisual({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{durationInFrames}=useVideoConfig();const p=.92+.08*Math.sin(frame/Math.max(1,durationInFrames)*Math.PI*4);const field=meta.fields?.[0];return <div style={{display:'flex',flexDirection:'column',alignItems:'center'}}><div style={{width:120,height:120,borderRadius:'50%',background:scene.accent,display:'grid',placeItems:'center',transform:`scale(${p})`,boxShadow:`0 16px 34px ${rgba(scene.accent,.28)}`}}><Icon name="arrowUp" color={inkOn(scene.accent,scene.accent2)} size={52}/></div><div style={{marginTop:22}}><VText scene={scene} kind={kind} id={field?.key||'label'} editorMode={editorMode} selected={selectedTextKey===(field?.key||'label')} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.impact,fontWeight:900,fontSize:46,color:scene.fg}}>{field?.text||'COMMENT ↓'}</VText></div></div>}

function CalloutVisual({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const fields=Object.fromEntries((meta.fields||[]).map(f=>[f.key,f]));const frame=useCurrentFrame(),{fps}=useVideoConfig();const s=enter(frame,fps);return <div style={{display:'flex',alignItems:'center',gap:28}}><div style={{width:190,height:350,borderRadius:34,background:'#1E2228',padding:12,boxShadow:'0 22px 44px rgba(0,0,0,.22)'}}><div style={{height:'100%',borderRadius:25,background:scene.bg,padding:'45px 18px 20px',position:'relative'}}>{[0,1,2,3].map((x,i)=><div key={i} style={{height:18,borderRadius:7,background:i===2?rgba(scene.accent,.24):rgba(scene.fg,.1),marginBottom:18,position:'relative'}}>{i===2?<div style={{position:'absolute',right:-8,top:-8,width:34,height:34,borderRadius:'50%',background:scene.accent,transform:`scale(${.75+.25*s})`}}/>:null}</div>)}</div></div><div style={{width:190,textAlign:'left'}}><VText scene={scene} kind={kind} id="title" editorMode={editorMode} selected={selectedTextKey==='title'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.bold,fontWeight:800,fontSize:30,color:scene.fg,textAlign:'left'}}>{fields.title?.text||'Settings'}</VText><div style={{marginTop:14}}><VText scene={scene} kind={kind} id="note" editorMode={editorMode} selected={selectedTextKey==='note'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:700,fontSize:23,color:scene.accent,textAlign:'left'}}>{fields.note?.text||'Tap here'}</VText></div><div style={{marginTop:18,transform:`translateX(${(1-s)*-24}px)`}}><Icon name="arrowRight" color={scene.accent} size={44}/></div></div></div>}

function StripVisual({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{durationInFrames}=useVideoConfig();const fields=(meta.fields||[]).slice(0,4);const p=pathProgress(frame,durationInFrames,.04,.7);const active=Math.min(fields.length-1,Math.floor(p*fields.length));return <div style={{width:470}}><div style={{display:'grid',gridTemplateColumns:`repeat(${fields.length},1fr)`,gap:8,padding:7,borderRadius:999,background:rgba(scene.fg,.07),border:`1px solid ${rgba(scene.fg,.1)}`}}>{fields.map((f,i)=><div key={f.key} style={{padding:'13px 8px',borderRadius:999,background:i===active?scene.accent:'transparent'}}><VText scene={scene} kind={kind} id={f.key} editorMode={editorMode} selected={selectedTextKey===f.key} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:750,fontSize:17,color:i===active?inkOn(scene.accent,scene.accent2):scene.fg}}>{f.text}</VText></div>)}</div>{meta.fields?.[4]?<div style={{marginTop:18}}><VText scene={scene} kind={kind} id={meta.fields[4].key} editorMode={editorMode} selected={selectedTextKey===meta.fields[4].key} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.bold,fontWeight:800,fontSize:22,color:scene.muted}}>{meta.fields[4].text}</VText></div>:null}</div>}

function CountdownVisual({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{durationInFrames}=useVideoConfig();const p=clamp(frame/Math.max(1,durationInFrames-1));const start=numberFromText(scene.visualBindings?.number||meta.fields?.find(f=>f.key==='number')?.text)||3;const n=Math.max(0,Math.ceil(start*(1-p)));const r=96,c=2*Math.PI*r;return <div style={{textAlign:'center'}}><div style={{width:280,height:280,position:'relative'}}><svg width="280" height="280" viewBox="0 0 280 280" style={{transform:'rotate(-90deg)'}}><circle cx="140" cy="140" r={r} fill="none" stroke={rgba(scene.fg,.12)} strokeWidth="18"/><circle cx="140" cy="140" r={r} fill="none" stroke={scene.accent} strokeWidth="18" strokeLinecap="round" strokeDasharray={c} strokeDashoffset={c*p}/></svg><div style={{position:'absolute',inset:0,display:'grid',placeItems:'center',font:`900 86px ${FONTS.mono}`,color:scene.fg}}>{n}</div></div><VText scene={scene} kind={kind} id="label" editorMode={editorMode} selected={selectedTextKey==='label'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:750,fontSize:22,color:scene.muted,letterSpacing:1.5}}>{meta.fields?.find(f=>f.key==='label')?.text||'SECONDS LEFT'}</VText></div>}


function ToastVisual({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){
  const frame=useCurrentFrame(),{fps}=useVideoConfig();const s=enter(frame,fps);const fields=Object.fromEntries((meta.fields||[]).map(f=>[f.key,f]));
  return <div style={{width:470,transform:`translateY(${(1-s)*-70}px)`,opacity:s}}>
    <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',padding:'0 14px 10px',font:`700 17px ${FONTS.body}`,color:scene.fg,opacity:.75}}><span>9:41</span><span>● ))) ▰</span></div>
    <div style={{padding:'18px 20px',borderRadius:22,background:luminance(scene.bg)<.5?'rgba(255,255,255,.08)':'rgba(255,255,255,.78)',border:`1px solid ${rgba(scene.fg,.12)}`,display:'flex',gap:16,alignItems:'flex-start',boxShadow:'0 18px 36px rgba(0,0,0,.16)'}}>
      <div style={{width:54,height:54,borderRadius:15,background:scene.accent,display:'grid',placeItems:'center',flex:'0 0 auto'}}><Icon name={meta.iconName||'check'} color={inkOn(scene.accent,scene.accent2)} size={30}/></div>
      <div style={{flex:1,minWidth:0}}>
        <div style={{display:'flex',justifyContent:'space-between',gap:14}}>
          <VText scene={scene} kind={kind} id="title" editorMode={editorMode} selected={selectedTextKey==='title'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.bold,fontWeight:800,fontSize:23,color:scene.fg,textAlign:'left'}}>{fields.title?.text||meta.label}</VText>
          <VText scene={scene} kind={kind} id="time" editorMode={editorMode} selected={selectedTextKey==='time'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:500,fontSize:15,color:scene.muted,textAlign:'right'}}>now</VText>
        </div>
        <VText scene={scene} kind={kind} id="message" editorMode={editorMode} selected={selectedTextKey==='message'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:550,fontSize:20,color:scene.muted,textAlign:'left',lineHeight:1.25,marginTop:7}}>{fields.message?.text||scene.visualBindings?.message||'NEW UPDATE'}</VText>
      </div>
    </div>
  </div>;
}

function ToggleVisual({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{durationInFrames}=useVideoConfig();const p=pathProgress(frame,durationInFrames,.05,.45);const field=meta.fields?.[0];return <div style={{textAlign:'center'}}><div style={{width:170,height:84,borderRadius:99,padding:8,background:p>.5?scene.accent:rgba(scene.fg,.12),position:'relative',transition:'none'}}><div style={{width:68,height:68,borderRadius:'50%',background:'#fff',boxShadow:'0 6px 16px rgba(0,0,0,.24)',transform:`translateX(${p*86}px)`}}/></div><div style={{marginTop:20}}><VText scene={scene} kind={kind} id={field?.key||'label'} editorMode={editorMode} selected={selectedTextKey===(field?.key||'label')} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:750,fontSize:24,color:scene.fg}}>{field?.text||meta.label}</VText></div></div>}

function FlowVisual({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{durationInFrames}=useVideoConfig();const p=pathProgress(frame,durationInFrames,.06,.72);const icons=['flag','target','arrowRight'];return <div style={{width:460,textAlign:'center'}}><div style={{display:'flex',alignItems:'center',justifyContent:'center'}}>{icons.map((ic,i)=><React.Fragment key={ic}><div style={{width:74,height:74,borderRadius:'50%',background:p>i/3?scene.accent:rgba(scene.fg,.1),display:'grid',placeItems:'center'}}><Icon name={ic} color={p>i/3?inkOn(scene.accent,scene.accent2):scene.fg} size={34}/></div>{i<2?<div style={{width:64,height:6,background:rgba(scene.fg,.1),overflow:'hidden'}}><div style={{height:'100%',width:`${clamp((p-i*.32)*3)*100}%`,background:scene.accent}}/></div>:null}</React.Fragment>)}</div>{meta.fields?.[0]?<div style={{marginTop:22}}><VText scene={scene} kind={kind} id={meta.fields[0].key} editorMode={editorMode} selected={selectedTextKey===meta.fields[0].key} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:650,fontSize:21,color:scene.muted}}>{meta.fields[0].text}</VText></div>:null}</div>}

function TrendVisual({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{fps}=useVideoConfig();const s=enter(frame,fps);const fields=Object.fromEntries((meta.fields||[]).map(f=>[f.key,f]));const value=scene.visualBindings?.value||scene.semantic?.data?.primary||(meta.requiresRealData?'—':fields.value?.text||'+42%');return <div style={{width:420,textAlign:'center'}}><svg viewBox="0 0 360 170" width="100%" height="210"><path d="M18 145 L85 120 L148 128 L210 76 L280 88 L340 28" fill="none" stroke={rgba(scene.muted,.5)} strokeWidth="5"/><path d="M210 105 L340 25 M340 25 L300 28 M340 25 L334 65" fill="none" stroke={scene.accent} strokeWidth="12" strokeLinecap="round" strokeLinejoin="round" strokeDasharray="220" strokeDashoffset={220*(1-s)}/></svg><VText scene={scene} kind={kind} id="value" editorMode={editorMode} selected={selectedTextKey==='value'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.mono,fontWeight:900,fontSize:62,color:scene.accent}}>{value}</VText><VText scene={scene} kind={kind} id="label" editorMode={editorMode} selected={selectedTextKey==='label'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:750,fontSize:22,color:scene.muted,marginTop:8}}>{fields.label?.text||meta.label}</VText></div>}

function BurstVisual({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{fps}=useVideoConfig();const s=enter(frame,fps);const field=meta.fields?.find(f=>['caption','label','text'].includes(f.key))||meta.fields?.[0];const icon=meta.iconName||'star';return <div style={{width:330,height:330,position:'relative',display:'grid',placeItems:'center'}}>{Array.from({length:10},(_,i)=>{const a=i/10*Math.PI*2;const d=110*s;return <div key={i} style={{position:'absolute',left:'50%',top:'50%',width:8,height:34,borderRadius:8,background:i%2?scene.accent:scene.accent2,transform:`translate(-50%,-50%) rotate(${a}rad) translateY(${-d}px)`,opacity:s}}/>})}<div style={{width:110,height:110,borderRadius:28,background:scene.bg,border:`2px solid ${rgba(scene.fg,.12)}`,display:'grid',placeItems:'center',zIndex:2,boxShadow:'0 14px 30px rgba(0,0,0,.15)'}}><Icon name={icon} color={scene.accent} size={56}/></div>{field?<div style={{position:'absolute',top:280,left:0,right:0}}><VText scene={scene} kind={kind} id={field.key} editorMode={editorMode} selected={selectedTextKey===field.key} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.bold,fontWeight:800,fontSize:25,color:scene.fg}}>{field.text}</VText></div>:null}</div>}

function Card3DVisual({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{durationInFrames}=useVideoConfig();const rot=Math.sin(frame/Math.max(1,durationInFrames)*Math.PI*2)*5;const fields=Object.fromEntries((meta.fields||[]).map(f=>[f.key,f]));const ink=inkOn(scene.accent,scene.accent2);return <div style={{width:440,padding:34,borderRadius:28,background:scene.accent,color:ink,boxShadow:'0 34px 54px rgba(0,0,0,.24)',transform:`perspective(900px) rotateY(${rot}deg) rotateX(${-rot*.35}deg)`}}><div style={{width:60,height:60,borderRadius:16,background:rgba(ink,.13),display:'grid',placeItems:'center'}}><Icon name="star" color={ink} size={34}/></div><VText scene={scene} kind={kind} id="title" editorMode={editorMode} selected={selectedTextKey==='title'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.bold,fontWeight:900,fontSize:38,color:ink,textAlign:'left',marginTop:28}}>{fields.title?.text||meta.label}</VText><VText scene={scene} kind={kind} id="subtitle" editorMode={editorMode} selected={selectedTextKey==='subtitle'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:600,fontSize:22,color:ink,textAlign:'left',opacity:.78,marginTop:10}}>{fields.subtitle?.text||''}</VText></div>}

function AvatarGroupVisual({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){
  const frame=useCurrentFrame(),{fps}=useVideoConfig();const count=scene.visualBindings?.count||'';
  return <div style={{textAlign:'center'}}><div style={{display:'flex',justifyContent:'center',alignItems:'center'}}>{[0,1,2,3,4].map((i)=>{const s=enter(frame,fps,i*2);return <div key={i} style={{width:74,height:74,borderRadius:'50%',marginLeft:i?-18:0,border:`4px solid ${scene.bg}`,background:i===4?rgba(scene.fg,.14):i%2?scene.accent:scene.accent2,transform:`scale(${.7+.3*s})`,display:'grid',placeItems:'center',color:scene.fg}}>{i===4?<VText scene={scene} kind={kind} id="count" editorMode={editorMode} selected={selectedTextKey==='count'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.mono,fontWeight:800,fontSize:18,color:scene.fg}}>{count||'+'}</VText>:null}</div>})}</div><div style={{marginTop:24}}><VText scene={scene} kind={kind} id="caption" editorMode={editorMode} selected={selectedTextKey==='caption'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:700,fontSize:24,color:scene.fg}}>{meta.fields?.[0]?.text||meta.label}</VText></div></div>;
}

function CompareTableVisual({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const f=Object.fromEntries((meta.fields||[]).map(x=>[x.key,x]));const rows=[f.f1,f.f2,f.f3].filter(Boolean);return <Frame scene={scene} width={470}><div style={{display:'grid',gridTemplateColumns:'1.4fr .7fr .7fr',gap:8,paddingBottom:12,font:`750 19px ${FONTS.body}`,color:scene.muted}}><span></span><VText scene={scene} kind={kind} id="colA" editorMode={editorMode} selected={selectedTextKey==='colA'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:750,fontSize:19,color:scene.muted}}>{f.colA?.text||'A'}</VText><VText scene={scene} kind={kind} id="colB" editorMode={editorMode} selected={selectedTextKey==='colB'} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:800,fontSize:19,color:scene.accent}}>{f.colB?.text||'B'}</VText></div>{rows.map((r,i)=><div key={r.key} style={{display:'grid',gridTemplateColumns:'1.4fr .7fr .7fr',gap:8,alignItems:'center',padding:'14px 0',borderTop:`1px solid ${rgba(scene.fg,.09)}`}}><VText scene={scene} kind={kind} id={r.key} editorMode={editorMode} selected={selectedTextKey===r.key} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:650,fontSize:19,color:scene.fg,textAlign:'left'}}>{r.text}</VText><div style={{display:'grid',placeItems:'center'}}><Icon name={i===0?'check':'cross'} color={i===0?'#1E8E5A':'#C0392B'} size={22}/></div><div style={{display:'grid',placeItems:'center'}}><Icon name="check" color="#1E8E5A" size={22}/></div></div>)}</Frame>}

function TypographyStatement({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){const frame=useCurrentFrame(),{fps}=useVideoConfig();const s=enter(frame,fps);const field=meta.fields?.[0];return <div style={{width:480,textAlign:'center',transform:`scale(${.82+.18*s})`}}><VText scene={scene} kind={kind} id={field?.key||'caption'} editorMode={editorMode} selected={selectedTextKey===(field?.key||'caption')} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.impact,fontWeight:900,fontSize:72,color:scene.fg,lineHeight:.92}}>{field?.text||meta.label}</VText><div style={{height:9,width:`${s*220}px`,background:scene.accent,borderRadius:10,margin:'22px auto 0'}}/></div>}

function GenericVisual({scene,kind,meta,editorMode,selectedTextKey,onSelectText}){return <Frame scene={scene} width={420}><div style={{display:'flex',alignItems:'center',gap:18}}><div style={{width:72,height:72,borderRadius:18,background:scene.accent,display:'grid',placeItems:'center'}}><Icon name={meta.iconName||'chart'} color={inkOn(scene.accent,scene.accent2)} size={38}/></div><div style={{flex:1}}>{(meta.fields||[]).slice(0,2).map(f=><VText key={f.key} scene={scene} kind={kind} id={f.key} editorMode={editorMode} selected={selectedTextKey===f.key} onSelect={onSelectText} baseStyle={{fontFamily:FONTS.body,fontWeight:700,fontSize:f.key==='value'?36:23,color:f.key==='value'?scene.fg:scene.muted,textAlign:'left',marginTop:4}}>{f.text}</VText>)}</div></div></Frame>}

export function VisualLibrary({kind,scene,editorMode=false,selectedTextKey='',onSelectText}){
  const meta=getVisualMeta(kind);if(!meta||kind==='none')return null;
  const props={scene,kind,meta,editorMode,selectedTextKey,onSelectText};
  switch(meta.type){
    case'hook':return <Hook {...props}/>;
    case'statSingle':return <StatSingle {...props}/>;
    case'ring':return <Ring {...props}/>;
    case'appCard':return <AppCard {...props}/>;
    case'grid4':case'statGrid':return <GridVisual {...props}/>;
    case'stack':return <StackVisual {...props}/>;
    case'checklist':return <Checklist {...props}/>;
    case'comparison':return <Compare {...props}/>;
    case'split':return <Compare {...props} split/>;
    case'priceTag':return <Offer {...props}/>;
    case'quote':return <Quote {...props}/>;
    case'barChart':return <Charts {...props} variant="bar"/>;
    case'lineChart':return <Charts {...props} variant="line"/>;
    case'pieChart':return <Charts {...props} variant="pie"/>;
    case'progressBar':return <ProgressBarVisual {...props}/>;
    case'counterUp':case'currencyStat':return <CounterVisual {...props}/>;
    case'timeline':return <Timeline {...props}/>;
    case'progressSteps':return <Timeline {...props} horizontal/>;
    case'device':return <Device {...props}/>;
    case'phone':return <Device {...props} meta={{...meta,deviceShape:'phone'}}/>;
    case'socialPost':return <SocialPost {...props}/>;
    case'toast':return <ToastVisual {...props}/>;
    case'badgeStamp':return <Badge {...props}/>;
    case'emojiPop':return <Reaction {...props}/>;
    case'map':return <MapVisual {...props}/>;
    case'beforeAfter':return <BeforeAfter {...props}/>;
    case'qrScan':return <QR {...props}/>;
    case'starRatingCard':return <StarRating {...props}/>;
    case'confettiBurst':return <Confetti {...props}/>;
    case'product':return <Product {...props}/>;
    case'kpiCard':return <StatSingle {...props}/>;
    case'compareTable':return <CompareTableVisual {...props}/>;
    case'cta':return <CTAVisual {...props}/>;
    case'trend':return <TrendVisual {...props}/>;
    case'bars':return <Charts {...props} variant="bar"/>;
    case'flow':return <FlowVisual {...props}/>;
    case'callout':return <CalloutVisual {...props}/>;
    case'strip':return <StripVisual {...props}/>;
    case'countdown':return <CountdownVisual {...props}/>;
    case'toggle':return <ToggleVisual {...props}/>;
    case'avatarGroup':return <AvatarGroupVisual {...props}/>;
    case'card3d':return <Card3DVisual {...props}/>;
    case'burst':return <BurstVisual {...props}/>;
    case'sparkle':return <BurstVisual {...props}/>;
    case'sweepBanner':case'neonGlowText':return <TypographyStatement {...props}/>;
    default:return <GenericVisual {...props}/>;
  }
}
